//  最新版本 3.2.1

    @GetMapping(value = "t")
    public void test(HttpServletResponse response) {
        ExcelWriter excelWriter = null;
        List<String> sheetLists = ListUtil.of("业务量统计", "日提报量表");
        try {
            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            excelWriter = EasyExcel.write(outputStream, UserModel.class).autoCloseStream(false).build();
            for (int i = 0; i < sheetLists.size(); i++) {
                WriteSheet writeSheet = EasyExcel.writerSheet(i, sheetLists.get(i))
                        .head(UserModel.class)
                        .build();
                excelWriter.write(userSaveService.list(), writeSheet);
            }
            // 数据为空，写入不进去
            System.out.println(outputStream.toByteArray().length);
        }
        catch (Exception e) {
            log.error("异常：", e);
        }
        finally {
            if (excelWriter != null) {
                excelWriter.finish();
            }
        }
    }
